const body = $input.first().json.body;
const p = body.prospect || {};
const r = body.result || {};
const s = r.summary || {};
const who = [p.full_name, p.job_title, p.company].filter(Boolean).join(', ');
const lines = [
  `:star: *Qualified lead* — ${who || 'unknown prospect'}`,
  `Phone: ${p.phone_normalized || p.phone || '—'}${p.email ? ` · ${p.email}` : ''}`,
  `Interest: ${r.interest_level} · Timeline: ${r.buying_timeline} · Role: ${r.decision_role}`,
  `Next action: ${r.next_action}${r.meeting_start ? ` (meeting ${r.meeting_start})` : ''}${r.callback_scheduled_for ? ` (callback ${r.callback_scheduled_for})` : ''}`,
  (r.pain_points || []).length ? `Pain points: ${r.pain_points.join('; ')}` : null,
  s.what_happened ? `_${s.what_happened}_` : null,
  s.next_step ? `Next step: ${s.next_step}` : null,
  `Call ${r.call_attempt_id} · ${body.event_id}`,
].filter(Boolean);
return [{ json: { text: lines.join('\n'), prospect: p, result: r } }];
